# Configure the Google Cloud Provider
provider "google" {
  project = var.project_id
  region  = var.region
}

# Create a random ID for the network
resource "random_id" "network_id" {
  byte_length = 8
}

# Enable the Compute Engine API
resource "google_project_service" "compute" {
  service = "compute.googleapis.com"
}

# Create the VPC network
module "vpc" {
  source  = "terraform-google-modules/network/google"
  version = "~> 5.0"

  project_id   = var.project_id
  network_name = "my-custom-vpc-${random_id.network_id.hex}"

  subnets = [
    {
      subnet_name   = var.subnet_1_name
      subnet_ip     = var.subnet_1_ip
      subnet_region = var.region_1
    },
    {
      subnet_name   = var.subnet_2_name
      subnet_ip     = var.subnet_2_ip
      subnet_region = var.region_2
    },
  ]

  secondary_ranges = {
    "${var.subnet_1_name}" = [
      {
        range_name    = "${var.subnet_1_name}-pod-cidr"
        ip_cidr_range = var.pod_1_cidr
      },
      {
        range_name    = "${var.subnet_1_name}-svc-cidr"
        ip_cidr_range = var.svc_1_cidr
      }
    ]
    "${var.subnet_2_name}" = [
      {
        range_name    = "${var.subnet_2_name}-pod-cidr"
        ip_cidr_range = var.pod_2_cidr
      },
      {
        range_name    = "${var.subnet_2_name}-svc-cidr"
        ip_cidr_range = var.svc_2_cidr
      }
    ]
  }
}

# Create firewall rules
resource "google_compute_firewall" "allow_http" {
  name    = "allow-http"
  network = module.vpc.network_id

  allow {
    protocol = "tcp"
    ports    = ["80"]
  }

  target_tags = ["http-server"]
}

resource "google_compute_firewall" "allow_https" {
  name    = "allow-https"
  network = module.vpc.network_id

  allow {
    protocol = "tcp"
    ports    = ["443"]
  }

  target_tags = ["https-server"]
}

# Create Cloud Router
resource "google_compute_router" "router" {
  name    = "router"
  network = module.vpc.network_id
  bgp {
    asn            = 64514
    advertise_mode = "CUSTOM"
  }
}

# Create NAT Gateway
resource "google_compute_router_nat" "nat" {
  name                               = "nat"
  router                             = google_compute_router.router.name
  region                             = var.region
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"
}

#########################################################################################
# This configuration creates a managed relational database on AWS (RDS), Azure (SQL Database), and GCP (Cloud SQL)
#
# Follow the directions here to set up a Terraform service account in AWS
# https://docs.aws.amazon.com/IAM/latest/UserGuide/id_roles_create_for-service.html
#
# Follow the directions here to set up a Terraform service principal in Azure
# https://docs.microsoft.com/en-us/azure/active-directory/develop/howto-create-service-principal-portal
#
# Follow the directions here to set up a Terraform service account in GCP
# https://cloud.google.com/community/tutorials/managing-gcp-projects-with-terraform
#
# Happy Terraforming!
#########################################################################################

###########################
# VARIABLES
############################

# AWS variables
variable "aws_region" {
  default = "us-west-2"
}
variable "aws_instance_class" {
  default = "db.t2.micro"
}
variable "aws_database_name" {}
variable "aws_database_username" {}
variable "aws_database_password" {}

# Azure variables
variable "azure_location" {
  default = "West US"
}
variable "azure_database_name" {}
variable "azure_database_username" {}
variable "azure_database_password" {}

# GCP variables
variable "gcp_region" {
  default = "us-central1"
}
variable "gcp_database_name" {}
variable "gcp_database_username" {}
variable "gcp_database_password" {}

############################
# PROVIDERS
############################

provider "aws" {
  version = "~> 3.0"
  region  = var.aws_region
}

provider "azurerm" {
  version = "~> 2.0"
  features {}
}

provider "google" {
  version = "~> 3.0"
  region  = var.gcp_region
}

############################
# RESOURCES
############################

# AWS RDS instance
resource "aws_db_instance" "example" {
  instance_class = var.aws_instance_class
  engine         = "postgres"
  name           = var.aws_database_name
  username       = var.aws_database_username
  password       = var.aws_database_password
}

# Azure SQL Database
resource "azurerm_sql_database" "example" {
  name                = var.azure_database_name
  resource_group_name = "example-resource-group"
  location            = var.azure_location
  server_name         = "example-sql-server"
}

resource "azurerm_sql_server" "example" {
  name                = "example-sql-server"
  resource_group_name = "example-resource-group"
  location            = var.azure_location
  version             = "12.0"
  administrator_login          = var.azure_database_username
  administrator_login_password = var.azure_database_password
}

# GCP Cloud SQL instance
resource "google_sql_database_instance" "example" {
  name                = "example-sql-instance"
  region              = var.gcp_region
  database_version   = "POSTGRES_13"
  deletion_protection = false
}

resource "google_sql_database" "example" {
  name     = var.gcp_database_name
  instance = google_sql_database_instance.example.name
}

resource "google_sql_user" "example" {
  name     = var.gcp_database_username
  instance = google_sql_database_instance.example.name
  host     = "%"
  password = var.gcp_database_password
}

# Configure the AWS Provider
provider "aws" {
  region = var.region
}

# Create a VPC
resource "aws_vpc" "ecs_vpc" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "ecs-vpc"
  }
}

# Create a subnet
resource "aws_subnet" "ecs_subnet" {
  vpc_id            = aws_vpc.ecs_vpc.id
  cidr_block        = var.subnet_cidr_block
  availability_zone = var.availability_zone

  tags = {
    Name = "ecs-subnet"
  }
}

# Create a security group for the ECS service
resource "aws_security_group" "ecs_sg" {
  name        = "ecs-sg"
  description = "Security group for ECS service"
  vpc_id      = aws_vpc.ecs_vpc.id

  # Allow inbound traffic on port 80
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Allow all outbound traffic
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-sg"
  }
}

# Create an ECS cluster
resource "aws_ecs_cluster" "ecs_cluster" {
  name = "ecs-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }
}

# Create an ECS task definition
resource "aws_ecs_task_definition" "ecs_task_definition" {
  family                = "ecs-task-definition"
  cpu                   = var.task_cpu
  memory                = var.task_memory
  network_mode          = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  execution_role_arn    = aws_iam_role.ecs_task_execution_role.arn
  container_definitions = jsonencode([
    {
      name      = "ecs-container"
      image      = var.container_image
      cpu        = var.container_cpu
      memory    = var.container_memory
      essential = true
      portMappings = [
        {
          containerPort = var.container_port
          hostPort      = var.container_port
          protocol      = "tcp"
        }
      ]
    }
  ])
}

# Create an IAM role for the ECS task execution
resource "aws_iam_role" "ecs_task_execution_role" {
  name        = "ecs-task-execution-role"
  description = "IAM role for ECS task execution"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

# Create an IAM policy for the ECS task execution
resource "aws_iam_policy" "ecs_task_execution_policy" {
  name        = "ecs-task-execution-policy"
  description = "IAM policy for ECS task execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchCheckLayerAvailability",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
        Effect    = "Allow"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "ecs_task_execution_policy_attachment" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = aws_iam_policy.ecs_task_execution_policy.arn
}

# Create an ALB target group
resource "aws_alb_target_group" "ecs_alb_target_group" {
  name        = "ecs-alb-target-group"
  port        = var.container_port
  protocol    = "HTTP"
  vpc_id      = aws_vpc.ecs_vpc.id
  target_type = "ip"
}

# Create an ALB listener
resource "aws_alb_listener" "ecs_alb_listener" {
  load_balancer_arn = aws_alb.ecs_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    target_group_arn = aws_alb_target_group.ecs_alb_target_group.arn
    type             = "forward"
  }
}

# Create an ALB
resource "aws_alb" "ecs_alb" {
  name            = "ecs-alb"
  subnets         = [aws_subnet.ecs_subnet.id]
  security_groups = [aws_security_group.ecs_sg.id]
}

# Create an ECS service
resource "aws_ecs_service" "ecs_service" {
  name            = "ecs-service"
  cluster         = aws_ecs_cluster.ecs_cluster.name
  task_definition = aws_ecs_task_definition.ecs_task_definition.arn
  desired_count   = var.desired_count
  launch_type      = "FARGATE"

  network_configuration {
    subnets          = [aws_subnet.ecs_subnet.id]
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = "ENABLED"
  }

  load_balancer {
    target_group_arn = aws_alb_target_group.ecs_alb_target_group.arn
    container_name   = "ecs-container"
    container_port   = var.container_port
  }
}

