  type        = map(string)
  description = "A map of tags to add to the KMS key"
  default     = {}
}

resource "aws_kms_key" "kms_key" {
  enable_key_rotation = true

  tags   = merge({ Name = var.kms_name }, var.tags)
  policy = data.aws_iam_policy_document.encryption_key.json
}

