  alias                  = "aks"
  host                   = module.aks.kube_config[0].host
  cluster_ca_certificate = base64decode(module.aks.kube_config[0].cluster_ca_certificate)

  exec {
    api_version = "client.authentication.k8s.io/v1beta1"
    command     = "az"
    args = [
      "account",
      "get-access-token",
      "--resource",
      "https://management.azure.com/",
    ]
  }
}

