  type        = string
  description = "Instance type for the Auto Scaling Group"
}

variable "asg_ami" {
  type        = string
  description = "AMI ID for the Auto Scaling Group"
}

variable "asg_key_name" {
  type        = string
  description = "Key name for the Auto Scaling Group"
}

variable "security_group_id" {
  type        = string
  description = "Security Group ID for the Auto Scaling Group"
}

variable "public_subnet_ids" {
  type        = list(string)
  description = "Public Subnet IDs for the Auto Scaling Group"
}

variable "min_size" {
  type        = number
  description = "Minimum size of the Auto Scaling Group"
}

variable "max_size" {
  type        = number
  description = "Maximum size of the Auto Scaling Group"
}

variable "desired_capacity" {
  type        = number
  description = "Desired capacity of the Auto Scaling Group"
}

variable "launch_template_version" {
  type        = string
  description = "Launch template version"
}

variable "user_data" {
  type        = string
  description = "User data for the launch template"
}

# Launch template
resource "aws_launch_template" "launch_template" {
  instance_type = var.asg_instance_type
  image_id      = var.asg_ami
  key_name      = var.asg_key_name
  network_interfaces {
    associate_public_ip_address = true
    security_groups             = [var.security_group_id]
  }
  user_data = var.user_data == null ? null : base64encode(file(var.user_data))
}

# Auto Scaling Group
resource "aws_autoscaling_group" "asg" {
  name                = var.asg_name
  min_size            = var.min_size
  max_size            = var.max_size
  desired_capacity    = var.desired_capacity
  vpc_zone_identifier = var.public_subnet_ids
  launch_template {
    id      = aws_launch_template.launch_template.id
    version = var.launch_template_version
  }
}

# Scaling policies
resource "aws_autoscaling_policy" "scale_up" {
  name                   = "scale-up"
  policy_type           = "SimpleScaling"
  autoscaling_group_name = aws_autoscaling_group.asg.name
  scaling_adjustment     = 1
  adjustment_type        = "ChangeInCapacity"
  cooldown               = 60
}

resource "aws_autoscaling_policy" "scale_down" {
  name                   = "scale-down"
  policy_type           = "SimpleScaling"
  autoscaling_group_name = aws_autoscaling_group.asg.name
  scaling_adjustment     = -1
  adjustment_type        = "ChangeInCapacity"
  cooldown               = 60
}

# CloudWatch metric alarms
resource "aws_cloudwatch_metric_alarm" "cpu_high" {
  alarm_name          = "cpu-high"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 1
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 300
  statistic           = "Average"
  threshold           = 80
  actions_enabled     = true
  alarm_actions       = [aws_autoscaling_policy.scale_up.arn]
}

resource "aws_cloudwatch_metric_alarm" "cpu_low" {
  alarm_name          = "cpu-low"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = 1
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 300
  statistic           = "Average"
  threshold           = 20
  actions_enabled     = true
  alarm_actions       = [aws_autoscaling_policy.scale_down.arn]
}

